<?php
namespace Modules\Finance\Http\Controllers;
use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Illuminate\Validation\Rule;use Modules\Core\Services\AuditService;use Modules\Core\Support\CurrentCompany;use Modules\Finance\Models\BankAccount;use Modules\Finance\Models\BankStatementImport;use Modules\Finance\Models\BankStatementLine;use Modules\Finance\Services\BankReconciliationService;use RuntimeException;
class BankReconciliationController extends Controller{public function __construct(private BankReconciliationService$service,private AuditService$audit){}public function accounts():JsonResponse{return response()->json(['data'=>BankAccount::where('company_id',CurrentCompany::id())->orderBy('code')->get()]);}public function createAccount(Request$r):JsonResponse{$c=CurrentCompany::id();$d=$r->validate(['code'=>'required|string|max:32','name'=>'required|string|max:255','bank_name'=>'required|string|max:255','currency_id'=>['nullable','integer',Rule::exists('currencies','id')->where('company_id',$c)],'coa_id'=>['required','integer',Rule::exists('chart_of_accounts','id')->where('company_id',$c)]]);$a=BankAccount::create($d+['company_id'=>$c,'created_by'=>$r->user()->id]);$this->audit->record('create',$a,after:$a->toArray(),request:$r);return response()->json($a,201);}public function import(Request$r,BankAccount$a):JsonResponse{$d=$r->validate(['statement_no'=>'required|string|max:64','period_start'=>'required|date_format:Y-m-d','period_end'=>'required|date_format:Y-m-d','opening_balance'=>'required|numeric','closing_balance'=>'required|numeric','rows'=>'required|array|min:1|max:5000','rows.*.transaction_date'=>'required|date_format:Y-m-d','rows.*.value_date'=>'nullable|date_format:Y-m-d','rows.*.direction'=>['required',Rule::in(['DEBIT','CREDIT'])],'rows.*.amount'=>'required|numeric|gt:0','rows.*.reference_no'=>'nullable|string|max:128','rows.*.description'=>'nullable|string|max:2000']);$rows=$d['rows'];unset($d['rows']);return$this->domain(fn()=>response()->json($this->service->import($a,$d,$rows,$r->user()),201));}public function show(BankStatementImport$s):JsonResponse{return response()->json($s->load('lines.matches'));}public function match(Request$r,BankStatementLine$l):JsonResponse{$d=$r->validate(['source_type'=>['required',Rule::in(['AR_PAYMENT','AP_PAYMENT'])],'source_id'=>'required|integer|min:1','amount'=>'required|numeric|gt:0']);return$this->domain(fn()=>response()->json($this->service->match($l,$d['source_type'],$d['source_id'],(float)$d['amount'],$r->user())));}public function ignore(Request$r,BankStatementLine$l):JsonResponse{$d=$r->validate(['reason'=>'required|string|max:500']);return$this->domain(fn()=>response()->json($this->service->ignore($l,$d['reason'],$r->user())));}public function fee(Request$r,BankStatementLine$l):JsonResponse{$d=$r->validate(['amount'=>'required|numeric|gt:0']);return$this->domain(fn()=>response()->json($this->service->bankFee($l,(float)$d['amount'],$r->user())));}public function reconcile(Request$r,BankStatementImport$s):JsonResponse{return$this->domain(fn()=>response()->json($this->service->reconcile($s,$r->user())));}private function domain(callable$c):JsonResponse{try{return$c();}catch(RuntimeException$e){return response()->json(['message'=>$e->getMessage()],422);}}}
